CREATE TABLE registration_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(190) NOT NULL, email VARCHAR(190) NOT NULL, organisation_id BIGINT UNSIGNED NOT NULL, profession_id BIGINT UNSIGNED NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING_VERIFICATION', reviewer_id BIGINT UNSIGNED NULL, reason VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(organisation_id) REFERENCES organisations(id), FOREIGN KEY(profession_id) REFERENCES master_data(id), FOREIGN KEY(reviewer_id) REFERENCES users(id), INDEX(email,status), CHECK(status IN ('PENDING_VERIFICATION','APPROVED','REJECTED','REQUEST_CORRECTION'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
